INSERT INTO agriculture_demo.service_areas(area_code,area_label,area_level) VALUES('DEMO-AGRI-A','Synthetic Central Zone','service_zone'),('DEMO-AGRI-B','Synthetic Lake Zone','service_zone') ON CONFLICT(area_code) DO NOTHING;
INSERT INTO agriculture_demo.farm_refs(farm_token,area_id,primary_crop,season_code) SELECT v.token,a.area_id,v.crop,'2026B' FROM (VALUES('FARM-DEMO-001','DEMO-AGRI-A','maize'),('FARM-DEMO-002','DEMO-AGRI-A','coffee'),('FARM-DEMO-003','DEMO-AGRI-B','beans')) v(token,area,crop) JOIN agriculture_demo.service_areas a ON a.area_code=v.area ON CONFLICT(farm_token) DO NOTHING;
INSERT INTO agriculture_demo.extension_visits(visit_ref,farm_id,visit_at,officer_ref,topic,outcome,finding_summary,follow_up_due) SELECT v.ref,f.farm_id,v.at_time,'DEMO-OFFICER',v.topic,v.outcome,v.summary,v.due FROM (VALUES('DEMO-VISIT-001','FARM-DEMO-001',TIMESTAMPTZ '2026-09-05 09:00+00','soil_management','completed','Synthetic soil guidance',DATE '2026-11-01'),('DEMO-VISIT-002','FARM-DEMO-002',TIMESTAMPTZ '2026-10-01 10:00+00','crop_health','follow_up','Synthetic leaf observation follow-up',DATE '2026-10-25'),('DEMO-VISIT-003','FARM-DEMO-003',TIMESTAMPTZ '2026-10-10 08:30+00','post_harvest','completed','Synthetic storage discussion',NULL)) v(ref,token,at_time,topic,outcome,summary,due) JOIN agriculture_demo.farm_refs f ON f.farm_token=v.token ON CONFLICT(visit_ref) DO NOTHING;
INSERT INTO agriculture_demo.input_deliveries(delivery_ref,farm_id,input_type,input_label,planned_qty,dispatched_qty,received_qty,unit_code,status,dispatch_ref,receipt_ref) SELECT v.ref,f.farm_id,v.typ,v.label,v.planned,v.dispatched,v.received,v.unit,v.status,v.dn,v.grn FROM (VALUES('DEMO-DEL-001','FARM-DEMO-001','seed','Synthetic maize seed',5::numeric,5::numeric,5::numeric,'kg','received','DEMO-DN-001','DEMO-GRN-001'),('DEMO-DEL-002','FARM-DEMO-002','tool','Synthetic pruning tools',2::numeric,2::numeric,1::numeric,'unit','disputed','DEMO-DN-002','DEMO-GRN-002'),('DEMO-DEL-003','FARM-DEMO-003','fertiliser','Synthetic input package',20::numeric,0::numeric,0::numeric,'kg','planned',NULL,NULL)) v(ref,token,typ,label,planned,dispatched,received,unit,status,dn,grn) JOIN agriculture_demo.farm_refs f ON f.farm_token=v.token ON CONFLICT(delivery_ref) DO NOTHING;